#define MAXE 1200005

int head[MAXN], to[MAXE], nxt[MAXE], ec;
int color[MAXN];
int queue[MAXN];

void addEdge(int u, int v) {
    ec++;
    to[ec] = v;
    nxt[ec] = head[u];
    head[u] = ec;
}

int main() {
    int N;
    if (scanf("%d", &N) != 1) return 0;

    for (int i = 1; i <= N; i++) head[i] = 0;
