        int M;
        scanf("%d", &M);
        for (int j = 0; j < M; j++) {
            int x;
            scanf("%d", &x);
            if (x == i) continue;
            addEdge(i, x);
            addEdge(x, i);
        }
    }

    for (int i = 1; i <= N; i++) color[i] = -1;

    int front = 0, back = 0;
    color[1] = 0;
    queue[back++] = 1;

    while (front < back) {
        int u = queue[front++];
        for (int e = head[u]; e != 0; e = nxt[e]) {
            int v = to[e];
            if (color[v] == -1) {
                color[v] = 1 - color[u];
                queue[back++] = v;
            }
        }
    }

    for (int i = 1; i <= N; i++) {
        if (color[i] == -1) {
            color[i] = 0;
