                int u = queue[front++];
                for (int e = head[u]; e != 0; e = nxt[e]) {
                    int v = to[e];
                    if (color[v] == -1) {
                        color[v] = 1 - color[u];
                        queue[back++] = v;
                    }
                }
            }
        }
    }

    int first = 1;
    for (int i = 1; i <= N; i++) {
        if (color[i] == 0) {
            if (!first) printf(" ");
            printf("%d", i);
            first = 0;
        }
    }
    printf("\n");

